mapper.select:
SELECT a.id, a.create_by AS createBy, a.create_date AS createDate, a.update_by AS updateBy, a.update_date AS updateDate, a.remarks, a.status, a.person_name AS personName, a.warning_type AS warningType, a.warning_content AS warningContent, DATE_ADD(a.warning_time, INTERVAL 8 HOUR) AS warningTime, a.alarm_record AS alarmRecord, DATE_ADD(a.alarm_time, INTERVAL 8 HOUR) AS alarmTime, a.trigger_reason AS triggerReason, a.handler, a.handle_time AS handleTime, a.handle_process AS handleProcess, a.handle_status AS handleStatus, a.attachment, a.device_id AS deviceId, a.id_card AS idCard, a.disposal_duration AS disposalDuration, a.x AS x, a.y AS y FROM swm_warning_management a WHERE a.id = #{id}
AND a.id_card = #{idCard}
LIMIT 1

SELECT a.id, a.create_by AS createBy, a.create_date AS createDate, a.update_by AS updateBy, a.update_date AS updateDate, a.remarks, a.status, a.person_name AS personName, a.warning_type AS warningType, a.warning_content AS warningContent, DATE_ADD(a.warning_time, INTERVAL 8 HOUR) AS warningTime, a.alarm_record AS alarmRecord, DATE_ADD(a.alarm_time, INTERVAL 8 HOUR) AS alarmTime, a.trigger_reason AS triggerReason, a.handler, a.handle_time AS handleTime, a.handle_process AS handleProcess, a.handle_status AS handleStatus, a.attachment, a.device_id AS deviceId, a.id_card AS idCard, a.disposal_duration AS disposalDuration, a.x AS x, a.y AS y FROM swm_warning_management a WHERE a.handle_status = '1'
AND a.person_name LIKE CONCAT('%', #{personName}, '%')
AND a.warning_type = #{warningType}
AND a.warning_content = #{warningContent}
AND a.warning_content != '一键SOS'
ORDER BY a.warning_time DESC
